class Solution {
    public String optimalDivision(int[] nums){
        if(nums.length==1)return String.valueOf(nums[0]);
        StringBuilder answer=new StringBuilder().append(nums[0]).append('/');
        if(nums.length>2)answer.append('(');
        for(int i=1;i<nums.length;i++){
            if(i>1)answer.append('/');
            answer.append(nums[i]);
        }
        if(nums.length>2)answer.append(')');
        return answer.toString();
    }
}

code.kotlin:
class Solution {
    fun optimalDivision(nums:IntArray):String{
        if(nums.size==1)return nums[0].toString();
        val suffix=nums.drop(1).joinToString("/");
        return if(nums.size==2)nums[0].toString()+"/"+suffix else nums[0].toString()+"/("+suffix+")"
    }
}

code.cpp:
class Solution {
    public: string optimalDivision(vector<int>& nums){
        if(nums.size()==1)return to_string(nums[0]);
        string suffix=to_string(nums[1]);
        for(int i=2;i<(int)nums.size();++i)suffix+="/"+to_string(nums[i]);
        return nums.size()==2?to_string(nums[0])+"/"+suffix:to_string(nums[0])+"/("+suffix+")";
    }
};
